class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        # Create a list to keep track of the last time each index can be marked
        last_mark_time = [0] * (n + 1)

        # Iterate over the changeIndices in reverse order
        for s in range(m - 1, -1, -1):
            index = changeIndices[s]
            if nums[index - 1] == 0:
                last_mark_time[index] = s + 1
            else:
                last_mark_time[index] = last_mark_time[index] + nums[index - 1]
                if last_mark_time[index] > m:
                    return -1

        # Find the maximum time required to mark all indices
        max_time = max(last_mark_time[1:])

        return max_time if max_time <= m else -1
